/// The value of [`indic_categories`].
#[inline]
pub(crate) fn indic_table(cp: u32) -> u32 {
    indic_table_inside(cp).unwrap_or(3584)
}

#[inline]
fn indic_table_inside(cp: u32) -> Option<u32> {
    let c = cp.checked_sub(0x2d)?;
    if c > 0x11dc4 {
        return None;
    }
    let i1 = get8(&INDIC_TABLE_S1, c >> 7)?;
    let i2 = get8(&INDIC_TABLE_S2, (i1 << 5) | ((c >> 2) & 0x1f))?;
    get16(&INDIC_TABLE_S3, (i2 << 2) | (c & 0x3))
}

/// HarfBuzz's `hb_indic_get_categories`: the category of the indic,
/// khmer and myanmar shapers in the low byte (the numbers of their
/// machines' exports), the position (`ot_position_t`) in the high byte.
#[inline]
pub(crate) fn indic_categories(cp: u32) -> u16 {
    u16::try_from(indic_table(cp)).unwrap_or(0x0e00)
}
